-- Each money column states, beside itself, why it is not a balance (doctrine §0.6: "No module holds its own balance").
-- The schema guard in src/bank-service.test.ts reads these from the live schema and fails on any numeric(38,18)
-- column without one, so the reason is written in the migration that adds the column, not in a list in the test
-- (project-state#3004: two journey PRs lost a push to that list). This file moves the list here, word for word.
--
-- Reversal: the matching .down.sql

COMMENT ON COLUMN "bank"."spaces"."goal_target" IS 'money: a savings TARGET the user set — never written by a money path';
COMMENT ON COLUMN "bank"."scheduled_transfers"."amount" IS 'money: the INSTRUCTION; a customer edit replaces it under a new revision, and the run posts the amount it locked';
COMMENT ON COLUMN "bank"."schedule_revisions"."amount" IS 'money: a RECORD of one replaced instruction; written once when an edit lands';
COMMENT ON COLUMN "bank"."transfer_executions"."amount" IS 'money: a RECORD of one completed firing; written once';
COMMENT ON COLUMN "bank"."dd_collections"."amount" IS 'money: a RECORD of what a creditor presented for one direct debit collection; written once';
COMMENT ON COLUMN "bank"."personal_transfers"."amount" IS 'money: a RECORD of one completed personal send; written once';
COMMENT ON COLUMN "bank"."received_holds"."amount" IS 'money: the INSTRUCTION one hold on received funds was placed for; written once, never summed: the held money is the ledger pot pay:recv:<transferId>';
COMMENT ON COLUMN "bank"."personal_send_reviews"."amount" IS 'money: the INSTRUCTION of one send held for review; written once, never summed, and nothing is reserved against it';
COMMENT ON COLUMN "bank"."personal_transfer_terms"."per_transfer_limit" IS 'money: a POLICY ceiling on one send; no money path writes it';
COMMENT ON COLUMN "bank"."personal_transfer_terms"."daily_limit" IS 'money: a POLICY ceiling on one UTC day; no money path writes it';
COMMENT ON COLUMN "bank"."personal_transfer_terms"."fee" IS 'money: a published POLICY fee, not a collected balance';
COMMENT ON COLUMN "bank"."limit_increase_requests"."requested" IS 'money: the limit a customer ASKED for; a request, never a balance';
COMMENT ON COLUMN "bank"."limit_increase_requests"."granted" IS 'money: a POLICY ceiling compliance granted one customer; no money path writes it';
COMMENT ON COLUMN "bank"."personal_requests"."amount" IS 'money: the amount asked for, an instruction until paid';
COMMENT ON COLUMN "bank"."earn_pools"."min_deposit" IS 'money: a POLICY floor on a single deposit';
COMMENT ON COLUMN "bank"."earn_positions"."principal" IS 'money: the deposit RECORD; interest is paid to available, never added here';
COMMENT ON COLUMN "bank"."interest_accruals"."paid_amount" IS 'money: a RECORD of one day; summing the table is the lifetime figure';
COMMENT ON COLUMN "bank"."earn_renewals"."principal" IS 'money: a RECORD of the amount one renewed term holds; written once, nothing posts with it';
COMMENT ON COLUMN "bank"."loan_products"."min_principal" IS 'money: a POLICY floor on a single draw; no money path writes it';
COMMENT ON COLUMN "bank"."loans"."principal" IS 'money: the amount DRAWN at open; recorded once, never revised — interest lives in its own table';
COMMENT ON COLUMN "bank"."loans"."opening_collateral" IS 'money: the opening PLEDGE amount at open — a TERM for id-reuse compares, write-once; live holdings are ledger + collateral events';
COMMENT ON COLUMN "bank"."loans"."last_mark_price" IS 'money: a PRICE, not a holding — what one unit of collateral was worth at the last accepted mark';
COMMENT ON COLUMN "bank"."loan_collateral_events"."amount" IS 'money: a RECORD of one completed lock or release; written once with its ledger tx id';
COMMENT ON COLUMN "bank"."loan_reserve_fundings"."amount" IS 'money: a RECORD of one successful reserve fund post; the independent half of reconcileReserve (B-02)';
COMMENT ON COLUMN "bank"."loan_interest_accruals"."principal_basis" IS 'money: the debt one day was computed against; a SNAPSHOT so that day is re-derivable';
COMMENT ON COLUMN "bank"."loan_interest_accruals"."interest_amount" IS 'money: a RECORD of one day''s charge; summing the table is the lifetime figure';
COMMENT ON COLUMN "bank"."loan_repayments"."interest_amount" IS 'money: a RECORD of one completed repayment; written once';
COMMENT ON COLUMN "bank"."loan_repayments"."principal_amount" IS 'money: a RECORD of one completed repayment; written once';
COMMENT ON COLUMN "bank"."loan_adjustments"."amount" IS 'money: a RECORD of one approved interest correction, signed; written once and never edited (append-only trigger)';
COMMENT ON COLUMN "bank"."loan_margin_calls"."cure_collateral_amount" IS 'money: a FIGURE quoted at one instant; the next mark writes a new row rather than revising this one';
COMMENT ON COLUMN "bank"."loan_liquidations"."mark_price" IS 'money: the PRICE one rung executed at, for the dispute nobody wants to have';
COMMENT ON COLUMN "bank"."loan_liquidations"."collateral_sold" IS 'money: a RECORD of one completed rung; written once';
COMMENT ON COLUMN "bank"."loan_liquidations"."proceeds" IS 'money: a RECORD of one completed rung; the four allocations below must sum to it';
COMMENT ON COLUMN "bank"."loan_liquidations"."principal_repaid" IS 'money: a RECORD of one completed rung; written once';
COMMENT ON COLUMN "bank"."loan_liquidations"."interest_repaid" IS 'money: a RECORD of one completed rung; written once';
COMMENT ON COLUMN "bank"."loan_liquidations"."penalty" IS 'money: a RECORD of one completed rung; written once';
COMMENT ON COLUMN "bank"."loan_liquidations"."surplus_returned" IS 'money: a RECORD of what went back to the borrower; written once';
COMMENT ON COLUMN "bank"."loan_liquidations"."shortfall" IS 'money: a RECORD of bad debt crystallised on a closing rung; written once';
COMMENT ON COLUMN "bank"."cards"."per_authorization_limit" IS 'money: a POLICY ceiling on ONE authorisation; it does not fall as the card is used and no money path writes it';
COMMENT ON COLUMN "bank"."cards"."daily_limit" IS 'money: a POLICY ceiling for a UTC day; NULL means no ceiling; spend is summed from authorisation records';
COMMENT ON COLUMN "bank"."cards"."monthly_limit" IS 'money: a POLICY ceiling for a UTC month; NULL means no ceiling; not a running total';
COMMENT ON COLUMN "bank"."cards"."cash_limit" IS 'money: a POLICY ceiling for ATM cash in a UTC day; NULL means no ceiling; not a remaining balance';
COMMENT ON COLUMN "bank"."card_authorizations"."amount" IS 'money: a RECORD of one authorisation request, in the funding asset; written once';
COMMENT ON COLUMN "bank"."card_settlements"."amount" IS 'money: a RECORD of one completed capture or reversal; written once with its ledger tx id';
COMMENT ON COLUMN "bank"."card_partner_refunds"."amount" IS 'money: the INSTRUCTION of one merchant refund sent to the card partner (OWNER 226); written once, the money is the partner’s and nothing posts with it';
COMMENT ON COLUMN "bank"."card_programme_funding_requests"."amount" IS 'money: the INSTRUCTION one programme funding request sent the card partner; written once, nothing posts with it (the partner moves the money)';
COMMENT ON COLUMN "bank"."card_programme_funding_requests"."threshold" IS 'money: a POLICY: the auto reload trigger sent to the card partner; no money path writes it';
COMMENT ON COLUMN "bank"."card_disputes"."amount" IS 'money: a RECORD of what one cardholder disputed on one settled capture; written once, nothing posts with it';
COMMENT ON COLUMN "bank"."card_disputes"."credit_amount" IS 'money: a RECORD of the provisional credit the card partner reports it gave its cardholder; the partner''s money, nothing posts with it';
COMMENT ON COLUMN "bank"."card_cashback"."amount" IS 'money: a RECORD of one reward; summing the table is the lifetime figure';
COMMENT ON COLUMN "bank"."card_cashback"."spend" IS 'money: a RECORD of what one partner-held capture spent, the base its wallet cashback was worked out on; the partner''s money, nothing posts with it';
COMMENT ON COLUMN "bank"."card_conversions"."settlement_amount" IS 'money: a RECORD of what the merchant charged, in their currency; written once';
COMMENT ON COLUMN "bank"."card_conversions"."funding_amount" IS 'money: a RECORD of what that converted to, and what the hold moved; written once';
COMMENT ON COLUMN "bank"."card_conversions"."rate" IS 'money: the RATE one authorisation was quoted at, frozen so a capture cannot re-quote; written once and never revised';
COMMENT ON COLUMN "bank"."ramp_onramps"."amount" IS 'money: a RECORD of one on-ramp credit; written once with its ledger tx id';
COMMENT ON COLUMN "bank"."ramp_offramps"."amount" IS 'money: a RECORD of one off-ramp instruction; written once with hold+settle tx ids';
COMMENT ON COLUMN "bank"."ramp_onramp_quotes"."amount" IS 'money: the crypto AMOUNT the customer asked to buy on one quote; not a balance';
COMMENT ON COLUMN "bank"."ramp_onramp_quotes"."pay_amount" IS 'money: the pay amount the rate source published for that quote; written once';
COMMENT ON COLUMN "bank"."ramp_onramp_quotes"."fee" IS 'money: the fee the rate source published for that quote; not a tariff this service computed';
COMMENT ON COLUMN "bank"."ramp_onramp_quotes"."rate" IS 'money: the rate the source published for that quote; frozen on the row';
COMMENT ON COLUMN "bank"."customer_onramps"."amount" IS 'money: a copy of the quote amount on one partner instruction; this row does not credit the ledger';
COMMENT ON COLUMN "bank"."customer_onramps"."pay_amount" IS 'money: the pay amount copied onto that instruction; written once';
COMMENT ON COLUMN "bank"."customer_onramps"."fee" IS 'money: the fee copied onto that instruction; written once';
COMMENT ON COLUMN "bank"."customer_onramps"."rate" IS 'money: the rate copied onto that instruction; written once';
COMMENT ON COLUMN "bank"."add_money_requests"."amount" IS 'money: the amount the customer asked to add on one request; kept refused or opened, never credited from here';
COMMENT ON COLUMN "bank"."add_money_requests"."credited_amount" IS 'money: a RECORD of what one paid request credited (the quote''s receive amount); written once with its ledger tx id';
COMMENT ON COLUMN "bank"."cash_out_requests"."amount" IS 'money: the amount the customer asked to cash out on one request; refused, or held, settled or given back under its own key';
COMMENT ON COLUMN "bank"."cash_out_requests"."fee" IS 'money: the partner''s fee for that one payout, copied once from its price; never charged from here';
COMMENT ON COLUMN "bank"."cash_out_requests"."receive_amount" IS 'money: what the partner said arrives for that one payout, copied once; not a balance';
COMMENT ON COLUMN "bank"."cash_out_requests"."returned_amount" IS 'money: a RECORD of what came back on one returned payout; credited once with its ledger tx id';
COMMENT ON COLUMN "bank"."rail_send_intents"."amount" IS 'money: the amount the customer asked to send over a bank rail on one intent; kept refused, never held or posted from here';
COMMENT ON COLUMN "bank"."api_move_quotes"."amount" IS 'money: the partner''s QUOTE: what one move between the person''s own accounts would move; written once';
COMMENT ON COLUMN "bank"."api_move_quotes"."fee" IS 'money: the partner''s QUOTE of what it takes for that move; null when it does not say; written once';
COMMENT ON COLUMN "bank"."api_move_quotes"."receives" IS 'money: the partner''s QUOTE of what arrives; null when the fee is not known; written once';
COMMENT ON COLUMN "bank"."api_payments"."amount" IS 'money: the INSTRUCTION of one payment out through the API; the partner holds and moves the money, nothing posts here';
COMMENT ON COLUMN "bank"."auto_invest_rules"."threshold" IS 'money: a POLICY keep-amount for a threshold sweep; instruction, not a holding';
COMMENT ON COLUMN "bank"."auto_invest_rules"."amount" IS 'money: a POLICY spend for a DCA schedule, or round-up granularity; instruction, not a holding';
COMMENT ON COLUMN "bank"."auto_invest_runs"."amount" IS 'money: a RECORD of one run (settled or rejected); written once';
COMMENT ON COLUMN "bank"."income_sorter_runs"."credit_amount" IS 'money: a RECORD of one posted payment from another person, as the ledger booked it; written once';
COMMENT ON COLUMN "bank"."income_sorter_run_legs"."amount" IS 'money: an INSTRUCTION fixed when the run is made: one split of that payment; written once';
COMMENT ON COLUMN "bank"."business_accounts"."spend_threshold" IS 'money: a POLICY dual-control floor; instruction, not a holding';
COMMENT ON COLUMN "bank"."business_control_requests"."spend_threshold" IS 'money: the PROPOSED floor on one dual-control request; written once, applied by copying it onto the account';
COMMENT ON COLUMN "bank"."business_approvals"."amount" IS 'money: a RECORD of one proposed/approved transfer; written once';
COMMENT ON COLUMN "bank"."business_payroll_lines"."amount" IS 'money: a RECORD of one payroll line; written once with the run';
COMMENT ON COLUMN "bank"."business_departments"."budget" IS 'money: a POLICY budget the owner set for one department; never written by a money path';
COMMENT ON COLUMN "bank"."business_payment_rules"."over_amount" IS 'money: a POLICY threshold above which a payment needs approvals; instruction, not a holding';
COMMENT ON COLUMN "bank"."business_payments"."amount" IS 'money: an INSTRUCTION: one payment proposed to the partner bank; written once when proposed';
COMMENT ON COLUMN "bank"."business_bills"."amount" IS 'money: a RECORD of what one bill says it asks for, reviewed by a person; never a holding';
COMMENT ON COLUMN "bank"."business_bill_vendors"."cap" IS 'money: a POLICY: the most a pre-approved vendor’s bill may be and still skip approvers';
COMMENT ON COLUMN "bank"."business_bill_limits"."per_payment" IS 'money: a POLICY Bill Pay limit the business set; blank refuses every payment';
COMMENT ON COLUMN "bank"."business_bill_limits"."daily" IS 'money: a POLICY Bill Pay limit the business set; blank refuses every payment';
COMMENT ON COLUMN "bank"."business_bill_limits"."monthly" IS 'money: a POLICY Bill Pay limit the business set; blank refuses every payment';
COMMENT ON COLUMN "bank"."business_bill_payments"."amount" IS 'money: an INSTRUCTION: one bill payment sent to the partner bank under its key; written once';
COMMENT ON COLUMN "bank"."business_bill_splits"."amount" IS 'money: a RECORD: one category line beside the partner’s one payment; written once with it';
COMMENT ON COLUMN "bank"."business_bulk_runs"."amount" IS 'money: an INSTRUCTION: one bulk run sent to the partner bank under its run key; written once at import';
COMMENT ON COLUMN "bank"."business_bulk_runs"."threshold" IS 'money: a POLICY: the business’s own threshold as it stood when the run was confirmed';
COMMENT ON COLUMN "bank"."business_bulk_lines"."amount" IS 'money: a RECORD: one recipient line beside the partner’s one instruction; written once at import';
COMMENT ON COLUMN "bank"."business_contractor_invoices"."amount" IS 'money: a RECORD of what one contractor invoice asks for; never a holding';
COMMENT ON COLUMN "bank"."business_contractor_batches"."amount" IS 'money: an INSTRUCTION: one contractor batch for the partner’s payout rail under its key; written once';
COMMENT ON COLUMN "bank"."business_contractor_batch_lines"."amount" IS 'money: a RECORD: one invoice line beside the batch’s one instruction; written once with it';
COMMENT ON COLUMN "bank"."business_crypto_payroll_members"."amount" IS 'money: a POLICY: what one member of a recurring crypto payroll is paid each run';
COMMENT ON COLUMN "bank"."business_crypto_payroll_runs"."amount" IS 'money: a RECORD of what the business’s own wallet signed for one month; INTAFACED holds none of it';
COMMENT ON COLUMN "bank"."business_crypto_payslips"."amount" IS 'money: a RECORD: one payslip of a run the business’s own wallet signed; never a holding';
COMMENT ON COLUMN "bank"."business_cards"."per_purchase_limit" IS 'money: a POLICY: the most one purchase on a business card may be; over it the card declines';
COMMENT ON COLUMN "bank"."business_card_purchases"."amount" IS 'money: an INSTRUCTION: one card capture sent to the partner bank under its purchase key; a declined one moves nothing';
COMMENT ON COLUMN "bank"."business_card_purchases"."receipt_over" IS 'money: a POLICY: the business’s receipt rule as it stood when the purchase was captured';
COMMENT ON COLUMN "bank"."business_card_limit_requests"."amount" IS 'money: a RECORD of the declined purchase an over-limit request asks the admins about';
COMMENT ON COLUMN "bank"."business_expense_policies"."receipt_over" IS 'money: a POLICY the business set: a captured purchase over it needs a receipt';
COMMENT ON COLUMN "bank"."business_reimbursements"."amount" IS 'money: an INSTRUCTION: one reimbursement sent to the partner bank under its claim key; written once';
COMMENT ON COLUMN "bank"."business_reimbursements"."member_before" IS 'money: a RECORD of the member’s balance as the partner reported it just before the move';
COMMENT ON COLUMN "bank"."business_reimbursements"."member_after" IS 'money: a RECORD of the member’s balance as the partner reported it just after the move';
COMMENT ON COLUMN "bank"."dormancy_notices"."fee" IS 'money: a RECORD of the fee one notice named; the debit, if any, is the partner move it names';
COMMENT ON COLUMN "bank"."budgets"."target" IS 'money: a POLICY: the monthly target the person chose for one spend category; spend is folded from the partner record or the ledger';
COMMENT ON COLUMN "bank"."recovery_sweeps"."amount" IS 'money: the PLAN of one recovery sweep round for one account, written before it posts; the ledger holds the balance';
COMMENT ON COLUMN "bank"."salary_credits"."amount" IS 'money: a RECORD of one payroll network credit as the network sent it; the money is the partner move it names';
COMMENT ON COLUMN "bank"."salary_split_legs"."amount" IS 'money: an INSTRUCTION: one split leg sent to the partner bank under its key, fixed when the credit arrived';
COMMENT ON COLUMN "bank"."pay_yourself_moves"."amount" IS 'money: an INSTRUCTION: one venue withdrawal the person prepared or signed under its move key; the venue and the partner record the money';
COMMENT ON COLUMN "bank"."pay_yourself_rules"."cap" IS 'money: a POLICY limit the person set: the most one weekly move may prepare';
